document.addEventListener("DOMContentLoaded",function(){const track=document.querySelector(".city-hero-v2 .hero-tags-bar");if(!track)return;const order=Array.prototype.slice.call(track.children);if(order.length<2)return;const mobile=window.matchMedia("(max-width: 1023.98px)");let timer=null;let running=false;let stepWidth=307;if(window.ResizeObserver&&order[0]){const ro=new ResizeObserver(function(entries){for(let i=0;i<entries.length;i++){const entry=entries[i];let width=0;if(entry.borderBoxSize&&entry.borderBoxSize.length>0){width=entry.borderBoxSize[0].inlineSize;}else if(entry.contentRect){width=entry.contentRect.width+32;}
if(width>0){stepWidth=Math.round(width)+12;}}});ro.observe(order[0]);}
function step(){return stepWidth;}
function park(){track.style.transition="none";track.style.transform="translateX(-"+step()+"px)";}
function advance(){track.style.transition="transform 0.5s ease";track.style.transform="translateX(-"+step()*2+"px)";}
track.addEventListener("transitionend",function(){if(!running)return;track.appendChild(track.firstElementChild);park();});function start(){running=true;track.insertBefore(track.lastElementChild,track.firstElementChild);park();timer=setInterval(advance,3000);}
function stop(){running=false;clearInterval(timer);timer=null;track.style.transition="";track.style.transform="";order.forEach(function(pill){track.appendChild(pill);});}
function sync(){if(mobile.matches&&!timer){start();}else if(!mobile.matches&&timer){stop();}}
sync();if(mobile.addEventListener){mobile.addEventListener("change",sync);}else if(mobile.addListener){mobile.addListener(sync);}});document.addEventListener("DOMContentLoaded",function(){const visual=document.querySelector(".city-hero-v2 .hero-visual");const form=document.querySelector(".city-hero-v2 #lead-form");if(!visual||!form)return;visual.addEventListener("click",function(event){if(!window.matchMedia("(max-width: 767.98px)").matches)return;if(event.target.closest("a, button, input, label, select, textarea"))return;const navbar=document.querySelector(".navbar");const offset=navbar?navbar.getBoundingClientRect().height:72;const top=form.getBoundingClientRect().top+window.pageYOffset-offset;window.scrollTo({top:top,behavior:"smooth"});});});